const ZERO_INFO={id:"zero",title:"Shunya — The Invention of Zero",originRegion:"Indian Subcontinent",eraOrigin:"Concept by 3rd Century BCE, formalized by 5th–7th Century CE",quickStats:[{label:"Sanskrit Name",value:"Shunya (शून्य)",icon:"0️⃣"},{label:"Earliest Symbol",value:"Bakhshali Manuscript, c. 3rd Century CE",icon:"📜"},{label:"Formal Rules",value:"Brahmagupta, 628 CE",icon:"🧮"},{label:"Oldest Inscribed Zero",value:"Chaturbhuj Temple, Gwalior, 876 CE",icon:"🛕"},{label:"Spread Via",value:"Arab Scholars to Europe",icon:"🌍"},{label:"Modern Role",value:"Foundation of Binary Computing",icon:"💻"}]},HISTORY_TEXT={title:"From Placeholder to Number",paragraphs:["Long before zero was treated as a number in its own right, Indian mathematicians used a placeholder dot (shunya-bindu) within their place-value system to mark an empty position — a concept already present in principle by the time of Pingala's work on prosody around the 3rd century BCE.","The Bakhshali Manuscript, a birch-bark text believed to date to as early as the 3rd century CE, contains some of the earliest known uses of a dot symbol to represent zero within calculations, showing that Indian scholars were already manipulating it as a working placeholder centuries before it was formalized.","The decisive leap came with the astronomer-mathematician Brahmagupta, who in his 628 CE treatise Brahmasphutasiddhanta laid down formal rules for arithmetic with zero — including addition, subtraction, and the effects of multiplying by zero — treating it, for the first time, as a number rather than a mere placeholder.","The oldest securely dated inscription of zero as a circular symbol in a place-value context is found on a stone tablet at the Chaturbhuj Temple in Gwalior, dated to 876 CE. From India, the numeral system carrying zero travelled to the Islamic world through scholars such as Al-Khwarizmi, and from there into Europe, eventually replacing Roman numerals across the world."]},TIMELINE=[{era:"c. 3rd Century BCE",title:"Conceptual Origins",description:"Pingala's writings on Sanskrit prosody use a concept equivalent to zero (shunya) while describing binary-like number patterns."},{era:"c. 3rd Century CE",title:"Bakhshali Manuscript",description:"One of the earliest surviving texts to use a dot symbol as a placeholder for zero in arithmetic calculations."},{era:"628 CE",title:"Brahmagupta's Rules",description:"Brahmagupta's Brahmasphutasiddhanta formally defines zero as a number and lays out rules for arithmetic operations involving it."},{era:"876 CE",title:"Gwalior Inscription",description:"The Chaturbhuj Temple inscription provides the oldest confirmed dated evidence of zero written as a circular numeral in a place-value system."},{era:"9th Century CE",title:"Transmission to the Arab World",description:"Scholars such as Al-Khwarizmi adopt the Indian numeral system, carrying the concept of zero into the Islamic Golden Age."},{era:"12th Century CE",title:"Arrival in Europe",description:"Fibonacci's Liber Abaci introduces the Hindu-Arabic numeral system, including zero, to European mathematics and commerce."},{era:"20th Century CE",title:"The Digital Age",description:"Zero becomes one of the two foundational digits of binary code, underpinning all modern computing."}],NUMBER_LINE_INFO={title:"Zero as the Anchor of the Number Line",description:"Drag the marker below to see how zero acts as the reference point that separates positive and negative numbers — a role it can only play once it is treated as a number, not just an empty placeholder."},COMPARISON_ROWS=[{aspect:"Place Value",before:"No symbol for an empty position; positions had to be inferred from context or spacing",after:"A explicit digit (0) marks an empty position, making numbers unambiguous"},{aspect:"Large Numbers",before:"Cumbersome tallying or additive systems (e.g. Roman numerals) for large quantities",after:"Compact positional notation can represent arbitrarily large numbers with few digits"},{aspect:"Arithmetic",before:"Subtraction and division involving 'nothing' had no consistent rules",after:"Brahmagupta's rules define addition, subtraction, and multiplication with zero"},{aspect:"Negative Numbers",before:"No natural reference point to define values less than nothing",after:"Zero anchors the number line, enabling negative numbers to be defined formally"},{aspect:"Algebra & Equations",before:"Equations could not express 'balance' or 'nullity' precisely",after:"Zero enables solving equations by isolating variables (x = 0 conditions)"},{aspect:"Computation",before:"No concept of a 'null' or 'off' state in mechanical calculation",after:"Zero and one form the basis of binary logic and digital computers"}],APPLICATIONS=[{title:"Binary Computing",description:"Every piece of digital data — from this page to spacecraft software — is ultimately encoded using just two digits: 0 and 1."},{title:"Place-Value Systems",description:"Zero lets the same ten digits represent any number, from single units to trillions, simply by their position."},{title:"Coordinate Systems & GPS",description:"Zero defines the origin point in coordinate geometry and geographic systems, from graphs to satellite navigation."},{title:"Physics & Engineering",description:"Concepts like absolute zero, null vectors, and equilibrium states all depend on zero as a true, calculable value."},{title:"Finance & Accounting",description:"Zero balances, break-even points, and null transactions all rely on zero being treated as a real, usable number."},{title:"Algebra & Calculus",description:"Solving equations, finding roots, and defining limits (approaching zero) are all built on zero's mathematical properties."}],REFERENCES=[{text:"Kaplan, R. — 'The Nothing That Is: A Natural History of Zero.'",link:"#"},{text:"Plofker, K. — 'Mathematics in India' (Princeton University Press).",link:"#"},{text:"Ifrah, G. — 'The Universal History of Numbers.'",link:"#"},{text:"Bodleian Library, Oxford — Bakhshali Manuscript research and radiocarbon dating findings.",link:"#"},{text:"Archaeological Survey of India — Chaturbhuj Temple, Gwalior, inscription records.",link:"#"}];